import React, { useState, useEffect } from "react";
import { useStatus } from "../contexts/StatusContext";
import { 
  UsersIcon, 
  TasksIcon, 
  ClockIcon, 
  CpuIcon,
  ArrowUpIcon,
  ArrowDownIcon,
  ErrorIcon
} from "./Icons";

interface StatCardProps {
  title: string;
  value: string | number;
  change?: string;
  changeType?: "increase" | "decrease" | "neutral";
  icon: React.ReactNode;
  color: "primary" | "success" | "warning" | "error" | "secondary";
}

const StatCard: React.FC<StatCardProps> = ({
  title,
  value,
  change,
  changeType = "neutral",
  icon,
  color,
}) => {
  const colorClasses = {
    primary: "gradient-primary",
    success: "gradient-success",
    warning: "gradient-warning",
    error: "gradient-error",
    secondary: "gradient-secondary",
  };

  const changeColorClasses = {
    increase: "text-success-600 bg-success-50",
    decrease: "text-error-600 bg-error-50",
    neutral: "text-secondary-600 bg-secondary-50",
  };

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
      <div className="flex items-center">
        <div className={`p-3 rounded-lg ${colorClasses[color]} text-white`}>
          {icon}
        </div>
        <div className="ml-4 flex-1">
          <p className="text-sm font-medium text-secondary-600 mb-1">{title}</p>
          <p className="text-2xl font-bold text-secondary-900">{value}</p>
          {change && (
            <div
              className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium mt-2 ${changeColorClasses[changeType]}`}
            >
              {changeType === "increase" && (
                <ArrowUpIcon size="sm" className="mr-1" />
              )}
              {changeType === "decrease" && (
                <ArrowDownIcon size="sm" className="mr-1" />
              )}
              {change}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

interface ProgressBarProps {
  label: string;
  value: number;
  max: number;
  color: "primary" | "success" | "warning" | "error";
}

const ProgressBar: React.FC<ProgressBarProps> = ({
  label,
  value,
  max,
  color,
}) => {
  const percentage = Math.min((value / max) * 100, 100);

  const colorClasses = {
    primary: "bg-primary-500",
    success: "bg-success-500",
    warning: "bg-warning-500",
    error: "bg-error-500",
  };

  return (
    <div className="mb-4">
      <div className="flex justify-between text-sm text-secondary-600 mb-1">
        <span>{label}</span>
        <span>
          {value}/{max}
        </span>
      </div>
      <div className="w-full bg-secondary-200 rounded-full h-2">
        <div
          className={`h-2 rounded-full transition-all duration-300 ${colorClasses[color]}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

interface ClientStatusProps {
  clients: any[];
}

const ClientStatus: React.FC<ClientStatusProps> = ({ clients }) => {
  const statusCounts = clients.reduce((acc, client) => {
    const status = client.connection_status || "disconnected";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});

  const statusItems = [
    {
      status: "connected",
      label: "Online",
      color: "success",
      count: statusCounts.connected || 0,
    },
    {
      status: "disconnected",
      label: "Offline",
      color: "error",
      count: statusCounts.disconnected || 0,
    },
    {
      status: "connecting",
      label: "Connecting",
      color: "warning",
      count: statusCounts.connecting || 0,
    },
    {
      status: "error",
      label: "Error",
      color: "error",
      count: statusCounts.error || 0,
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-4">
        Client Status
      </h3>
      <div className="space-y-3">
        {statusItems.map(
          (item) =>
            item.count > 0 && (
              <div
                key={item.status}
                className="flex items-center justify-between"
              >
                <div className="flex items-center">
                  <div
                    className={`w-3 h-3 rounded-full mr-3 ${
                      item.color === "success"
                        ? "status-online"
                        : item.color === "warning"
                          ? "status-warning"
                          : "status-offline"
                    }`}
                  />
                  <span className="text-sm text-secondary-600">
                    {item.label}
                  </span>
                </div>
                <span className="text-sm font-medium text-secondary-900">
                  {item.count}
                </span>
              </div>
            ),
        )}
        {clients.length === 0 && (
          <div className="text-center py-4">
            <p className="text-sm text-secondary-500">No clients connected</p>
          </div>
        )}
      </div>
    </div>
  );
};

// Quick Stats Card Component
interface QuickStatProps {
  title: string;
  value: string | number;
  subtitle?: string;
  icon: string;
  trend?: {
    value: string;
    isPositive: boolean;
  };
  color: 'blue' | 'green' | 'yellow' | 'red' | 'purple' | 'indigo';
}

const QuickStat: React.FC<QuickStatProps> = ({ title, value, subtitle, icon, trend, color }) => {
  const gradientClasses = {
    blue: 'gradient-primary',
    green: 'gradient-success', 
    yellow: 'gradient-warning',
    red: 'gradient-error',
    purple: 'gradient-secondary',
    indigo: 'gradient-info',
  };

  return (
    <div className={`bg-white rounded-xl shadow-sm p-6 card-hover border border-secondary-100`}>
      <div className="flex items-center justify-between">
        <div className="flex-1">
          <p className="text-sm font-medium text-secondary-700 mb-2">{title}</p>
          <p className="text-3xl font-bold text-secondary-900">{value}</p>
          {subtitle && (
            <p className="text-xs text-secondary-600 mt-2">{subtitle}</p>
          )}
          {trend && (
            <div className={`inline-flex items-center mt-3 px-3 py-1 rounded-full text-xs font-medium ${
              trend.isPositive ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
            }`}>
              <span className="mr-1">{trend.isPositive ? '↗' : '↘'}</span>
              {trend.value}
            </div>
          )}
        </div>
        <div className={`w-16 h-16 rounded-xl ${gradientClasses[color]} flex items-center justify-center text-white text-2xl shadow-md`}>
          <span>{icon}</span>
        </div>
      </div>
    </div>
  );
};

// System Health Component
const SystemHealth: React.FC = () => {
  const { state } = useStatus();

  const healthItems = [
    {
      name: 'WebSocket Server',
      description: 'Real-time communication',
      status: state.connectionStatus === 'connected'
    },
    {
      name: 'Redis Cache',
      description: 'Data caching layer',
      status: state.health?.redis || false
    },
    {
      name: 'Client Manager',
      description: 'Connection management',
      status: state.health?.client_manager || false
    },
    {
      name: 'Task Router',
      description: 'Task distribution',
      status: state.health?.task_router || false
    }
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">💻 Стан системи</h3>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {healthItems.map((item, index) => (
          <div key={item.name} className={`flex items-center justify-between p-4 bg-secondary-50 rounded-lg`}>
            <div className="flex-1">
              <p className="text-sm font-medium text-secondary-900">{item.name}</p>
              <p className="text-xs text-secondary-600">{item.description}</p>
            </div>
            <div className={`w-4 h-4 rounded-full ${
              item.status ? 'status-online' : 'status-offline'
            }`} />
          </div>
        ))}
      </div>

      {state.health?.version && (
        <div className="mt-4 pt-4 border-t border-secondary-200">
          <p className="text-xs text-secondary-500">
            Версія системи: <span className="font-medium">{state.health.version}</span>
          </p>
        </div>
      )}
    </div>
  );
};

// Resource Monitor Component
const ResourceMonitor: React.FC = () => {
  const { state } = useStatus();

  const getUsageColor = (value: number) => {
    if (value > 80) return 'bg-red-500';
    if (value > 60) return 'bg-yellow-500';
    return 'bg-green-500';
  };

  const resources = [
    {
      name: 'CPU',
      value: state.metrics?.system?.cpu_usage || 0,
      icon: '🖥️'
    },
    {
      name: 'Пам\'ять',
      value: state.metrics?.system?.memory_usage || 0,
      icon: '💾'
    },
    {
      name: 'Диск',
      value: state.metrics?.system?.disk_usage || 0,
      icon: '💿'
    }
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">📊 Ресурси системи</h3>

      <div className="space-y-6">
        {resources.map((resource, index) => (
          <div key={resource.name} className={`space-y-3 p-4 bg-secondary-50 rounded-lg`}>
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <span className="text-2xl">{resource.icon}</span>
                <span className="text-base font-medium text-secondary-800">{resource.name}</span>
              </div>
              <span className="text-lg font-bold text-secondary-900">{Math.round(resource.value)}%</span>
            </div>
            <div className="w-full bg-secondary-200 rounded-full h-3">
              <div
                className={`h-3 rounded-full transition-all duration-500 ${getUsageColor(resource.value)}`}
                style={{ width: `${Math.min(resource.value, 100)}%` }}
              />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// Live Activity Feed Component
const LiveActivityFeed: React.FC = () => {
  const { state } = useStatus();
  const [activities, setActivities] = useState<Array<{
    id: string;
    type: 'connection' | 'disconnection' | 'task' | 'error';
    message: string;
    timestamp: Date;
  }>>([]);

  useEffect(() => {
    // Simulate live activity based on state changes
    const newActivity = {
      id: Date.now().toString(),
      type: 'connection' as const,
      message: `${state.clients.length} клієнтів підключено`,
      timestamp: new Date()
    };

    setActivities(prev => [newActivity, ...prev.slice(0, 9)]);
  }, [state.clients.length]);

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'connection': return '🔗';
      case 'disconnection': return '🔌';
      case 'task': return '⚡';
      case 'error': return '❌';
      default: return '📝';
    }
  };

  const getActivityColor = (type: string) => {
    switch (type) {
      case 'connection': return 'text-green-600';
      case 'disconnection': return 'text-red-600';
      case 'task': return 'text-blue-600';
      case 'error': return 'text-red-600';
      default: return 'text-secondary-600';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">📡 Жива активність</h3>

      <div className="space-y-3 max-h-80 overflow-y-auto">
        {activities.length > 0 ? activities.map((activity) => (
          <div key={activity.id} className="flex items-start space-x-3 p-3 bg-secondary-50 rounded-lg">
            <span className="text-lg">{getActivityIcon(activity.type)}</span>
            <div className="flex-1 min-w-0">
              <p className={`text-sm font-medium ${getActivityColor(activity.type)}`}>
                {activity.message}
              </p>
              <p className="text-xs text-secondary-500">
                {activity.timestamp.toLocaleTimeString()}
              </p>
            </div>
          </div>
        )) : (
          <div className="text-center py-8">
            <p className="text-sm text-secondary-500">Очікування активності...</p>
          </div>
        )}
      </div>
    </div>
  );
};

// Network Statistics Component
const NetworkStats: React.FC = () => {
  const { state } = useStatus();
  const [networkData, setNetworkData] = useState({
    bytesIn: 0,
    bytesOut: 0,
    packetsIn: 0,
    packetsOut: 0
  });

  useEffect(() => {
    // Simulate network data
    const interval = setInterval(() => {
      setNetworkData(prev => ({
        bytesIn: prev.bytesIn + Math.random() * 1000,
        bytesOut: prev.bytesOut + Math.random() * 800,
        packetsIn: prev.packetsIn + Math.floor(Math.random() * 10),
        packetsOut: prev.packetsOut + Math.floor(Math.random() * 8)
      }));
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">🌐 Мережева статистика</h3>

      <div className="grid grid-cols-2 gap-4">
        <div className="text-center p-4 bg-blue-50 rounded-lg">
          <p className="text-2xl font-bold text-blue-600">{formatBytes(networkData.bytesIn)}</p>
          <p className="text-sm text-blue-700">Вхідний трафік</p>
          <p className="text-xs text-blue-500 mt-1">{networkData.packetsIn} пакетів</p>
        </div>
        <div className="text-center p-4 bg-green-50 rounded-lg">
          <p className="text-2xl font-bold text-green-600">{formatBytes(networkData.bytesOut)}</p>
          <p className="text-sm text-green-700">Вихідний трафік</p>
          <p className="text-xs text-green-500 mt-1">{networkData.packetsOut} пакетів</p>
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-secondary-200">
        <div className="flex justify-between text-xs text-secondary-500">
          <span>Активних з'єднань: {state.clients.filter(c => c.connection_status === 'connected').length}</span>
          <span>Всього клієнтів: {state.clients.length}</span>
        </div>
      </div>
    </div>
  );
};

// Performance Metrics Component
const PerformanceMetrics: React.FC = () => {
  const { state } = useStatus();
  const [metrics, setMetrics] = useState({
    responseTime: 0,
    throughput: 0,
    errorRate: 0
  });

  useEffect(() => {
    // Simulate performance metrics
    const interval = setInterval(() => {
      setMetrics({
        responseTime: 50 + Math.random() * 100,
        throughput: 100 + Math.random() * 50,
        errorRate: Math.random() * 5
      });
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6">⚡ Продуктивність</h3>

      <div className="space-y-4">
        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">Час відповіді</span>
          <span className="text-lg font-bold text-blue-600">{Math.round(metrics.responseTime)}ms</span>
        </div>

        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">Пропускна здатність</span>
          <span className="text-lg font-bold text-green-600">{Math.round(metrics.throughput)} req/s</span>
        </div>

        <div className="flex justify-between items-center">
          <span className="text-sm text-secondary-600">Рівень помилок</span>
          <span className={`text-lg font-bold ${metrics.errorRate > 2 ? 'text-red-600' : 'text-green-600'}`}>
            {metrics.errorRate.toFixed(1)}%
          </span>
        </div>

        {state.health?.uptime && (
          <div className="pt-4 border-t border-secondary-200">
            <div className="flex justify-between items-center">
              <span className="text-sm text-secondary-600">Час роботи</span>
              <span className="text-lg font-bold text-purple-600">
                {Math.floor(state.health.uptime / 3600)}h {Math.floor((state.health.uptime % 3600) / 60)}m
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export const Dashboard: React.FC = () => {
  const { state } = useStatus();

  // Calculate quick stats
  const totalClients = state.clients.length;
  const connectedClients = state.clients.filter(c => c.connection_status === 'connected').length;
  const connectionRate = totalClients > 0 ? (connectedClients / totalClients * 100) : 0;
  const avgCpuUsage = state.metrics?.system?.cpu_usage || 0;
  const avgMemoryUsage = state.metrics?.system?.memory_usage || 0;

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="text-center">
        <h1 className="text-4xl font-bold text-gradient mb-4">
          🚀 TetraCore StreamHub
        </h1>
        <p className="text-xl text-secondary-600">
          Центральна панель моніторингу та управління
        </p>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <QuickStat
          title="Активні клієнти"
          value={connectedClients}
          subtitle={`з ${totalClients} загалом`}
          icon="👥"
          trend={{
            value: `${connectionRate.toFixed(0)}% онлайн`,
            isPositive: connectionRate > 50
          }}
          color="blue"
        />

        <QuickStat
          title="Навантаження CPU"
          value={`${Math.round(avgCpuUsage)}%`}
          subtitle="Середнє використання"
          icon="🖥️"
          trend={{
            value: avgCpuUsage > 70 ? 'Високе' : 'Нормальне',
            isPositive: avgCpuUsage <= 70
          }}
          color={avgCpuUsage > 70 ? 'red' : 'green'}
        />

        <QuickStat
          title="Використання пам'яті"
          value={`${Math.round(avgMemoryUsage)}%`}
          subtitle="Оперативна пам'ять"
          icon="💾"
          trend={{
            value: avgMemoryUsage > 80 ? 'Критично' : 'Стабільно',
            isPositive: avgMemoryUsage <= 80
          }}
          color={avgMemoryUsage > 80 ? 'red' : 'green'}
        />

        <QuickStat
          title="Стан системи"
          value={state.health?.status === 'healthy' ? 'Здорова' : 'Проблеми'}
          subtitle="Загальний статус"
          icon="❤️"
          color={state.health?.status === 'healthy' ? 'green' : 'red'}
        />
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column */}
        <div className="lg:col-span-2 space-y-6">
          <SystemHealth />
          <ResourceMonitor />
        </div>

        {/* Right Column */}
        <div className="space-y-6">
          <LiveActivityFeed />
          <PerformanceMetrics />
        </div>
      </div>

      {/* Bottom Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <NetworkStats />

        {/* Alerts Panel */}
        <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-6">🚨 Системні сповіщення</h3>

          {state.alerts.length > 0 ? (
            <div className="space-y-3">
              {state.alerts.slice(0, 4).map((alert) => (
                <div
                  key={alert.id}
                  className={`p-3 rounded-lg border-l-4 ${
                    alert.type === 'error'
                      ? 'bg-red-50 border-red-500'
                      : alert.type === 'warning'
                      ? 'bg-yellow-50 border-yellow-500'
                      : 'bg-blue-50 border-blue-500'
                  }`}
                >
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <p className="text-sm font-medium text-secondary-900">{alert.title}</p>
                      <p className="text-xs text-secondary-600 mt-1">{alert.message}</p>
                    </div>
                    <span className="text-xs text-secondary-500">
                      {new Date(alert.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8">
              <p className="text-sm text-secondary-500">✅ Немає активних сповіщень</p>
            </div>
          )}
        </div>
      </div>

      {/* Status Indicators */}
      {state.isLoading && (
        <div className="fixed bottom-6 right-6 bg-white rounded-lg shadow-lg p-4 flex items-center space-x-3 border border-secondary-200">
          <div className="w-5 h-5 border-2 border-primary-600 border-t-transparent rounded-full animate-spin"></div>
          <span className="text-sm text-secondary-600">Оновлення даних...</span>
        </div>
      )}

      {state.error && (
        <div className="fixed bottom-6 right-6 bg-red-50 border border-red-200 rounded-lg p-4 max-w-sm">
          <div className="flex items-start space-x-3">
            <span className="text-red-500 text-lg">❌</span>
            <div>
              <p className="text-sm font-medium text-red-900">Помилка з'єднання</p>
              <p className="text-xs text-red-700 mt-1">{state.error}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
